//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::length`; the
//! native twin is `benches/native/Bench/StringLength.lean`.
//! NOT comparable: Lean reads the count cached in the string; this counts the bytes, the count a translator caches when it makes a string

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::string;
use lean_runtime_bench::{mixed, run, step, SEED};
use std::hint::black_box;
#[allow(unused_variables)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let k = s.len() as u64;
    let m = k + 2;
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(string::length(black_box(s)));
    }
    acc as u64
}

fn main() {
    run(|| mixed(), kernel)
}
